+/// Opt-in, thread-owned observation of the existing IVK call only. Recording
+/// clones handles; it never materializes native constants or allocates nodes.
+#[cfg(feature = "formal-observer")]
+pub mod inspection {
+    use super::*;
+    use commonware_cryptography::zk::circuit::CircuitIdx;
+    use std::cell::RefCell;
+    thread_local! {
+        static CALLS: RefCell<Option<Vec<[Option<CircuitIdx>; 4]>>> = const { RefCell::new(None) };
+    }
+    pub struct Capture { _thread: std::marker::PhantomData<std::rc::Rc<()>> }
+    impl Drop for Capture {
+        fn drop(&mut self) { CALLS.with(|calls| *calls.borrow_mut() = None); }
+    }
+    pub fn begin() -> anyhow::Result<Capture> {
+        CALLS.with(|calls| {
+            let mut calls = calls.borrow_mut();
+            anyhow::ensure!(calls.is_none(), "nested IVK capture");
+            *calls = Some(Vec::new());
+            Ok(Capture { _thread: std::marker::PhantomData })
+        })
+    }
+    pub(super) fn record(values: &[Var<'_, Scalar>; 4]) {
+        CALLS.with(|calls| {
+            if let Some(calls) = calls.borrow_mut().as_mut() {
+                // Two entries suffice to diagnose a changed call count, without
+                // affecting ordinary construction outside an active session.
+                if calls.len() < 2 { calls.push(values.each_ref().map(|v| v.inspect_circuit_idx())); }
+            }
+        });
+    }
+    pub fn take() -> anyhow::Result<[CircuitIdx; 4]> {
+        CALLS.with(|calls| {
+            let mut calls = calls.borrow_mut();
+            let calls = calls.as_mut().ok_or_else(|| anyhow::anyhow!("inactive IVK capture"))?;
+            anyhow::ensure!(calls.len() == 1, "expected exactly one IVK call");
+            let handles = calls.pop().unwrap();
+            anyhow::ensure!(handles.iter().all(Option::is_some), "native IVK handle unsupported");
+            Ok(handles.map(Option::unwrap))
+        })
+    }
+    #[cfg(test)]
+    mod tests {
+        use super::*;
+        #[test]
+        fn session_is_exclusive_and_cleans_up_on_error_and_panic() {
+            { let _capture = begin().unwrap(); assert!(begin().is_err()); assert!(take().is_err()); }
+            let result = std::panic::catch_unwind(|| { let _capture = begin().unwrap(); panic!("synthetic IVK failure"); });
+            assert!(result.is_err());
+            { let _capture = begin().unwrap(); assert!(take().is_err()); }
+            assert!(take().is_err());
+        }
+    }
+}
